import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    requests = input_data[1:]

    db = {}

    for name in requests:
        if name not in db:
            db[name] = 0
            print("OK")
        else:
            count = db[name]
            count += 1
            db[name] = count
            new_name = f"{name}{count}"
            while new_name in db:
                count += 1
                db[name] = count
                new_name = f"{name}{count}"
            db[new_name] = 0
            print(new_name)

if __name__ == "__main__":
    main()
